import { unstable_cache } from "next/cache";

export type Product = {
  sku: string;
  name: string;
  price: number;
  inventory: number;
  available: boolean;
};

// In-memory canonical catalog (simulates DB/ERP source).
// In production, this would be a database or external API.
let catalog: Product[] = [
  { sku: "SKU-001", name: "Widget Pro", price: 29.99, inventory: 150, available: true },
  { sku: "SKU-002", name: "Gadget Plus", price: 49.99, inventory: 0, available: false },
  { sku: "SKU-003", name: "Tool Kit Basic", price: 19.99, inventory: 320, available: true },
  { sku: "SKU-004", name: "Premium Bundle", price: 99.99, inventory: 45, available: true },
  { sku: "SKU-005", name: "Spare Part X", price: 4.99, inventory: 1200, available: true },
];

export function getCatalog(): Product[] {
  return catalog;
}

export function setCatalog(products: Product[]): void {
  catalog = products;
}

async function fetchProductsFromSource(): Promise<Product[]> {
  return getCatalog();
}

export const getProducts = unstable_cache(
  async (): Promise<Product[]> => {
    return fetchProductsFromSource();
  },
  ["products"],
  { tags: ["products"] }
);

