import { revalidateTag } from "next/cache";
import type { Product } from "./products";
import { getCatalog, setCatalog } from "./products";

/**
 * Simulates fetching latest catalog from upstream ERP/PIM.
 * In production, this would call your ERP/PIM API.
 */
async function fetchFromErp(): Promise<Product[]> {
  // Simulate network latency and processing (e.g. thousands of SKUs)
  await new Promise((r) => setTimeout(r, 50));

  const current = getCatalog();
  // Simulate upstream changes: slight price/inventory tweaks
  const now = Date.now();
  return current.map((p, i) => {
    const newInventory = Math.max(0, p.inventory + ((now + i) % 7) - 3);
    return {
      ...p,
      price: Math.round((p.price * (1 + (i % 3) * 0.01)) * 100) / 100,
      inventory: newInventory,
      available: newInventory > 0,
    };
  });
}

/**
 * Runs the full sync: fetch from ERP, update catalog, invalidate cache.
 * Called in the background; does not block the request.
 */
export async function runCatalogSync(): Promise<void> {
  const products = await fetchFromErp();
  setCatalog(products);
  revalidateTag("products");
}

